package app

const dashboard = `<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AGI Hub</title>
<style>
:root{font:15px/1.6 system-ui,sans-serif;color:#e3e9f2;background:#10151e}body{margin:0}main{max-width:1120px;margin:auto;padding:36px 24px}h1{font-size:26px;font-weight:600;margin:0}p{color:#99a8bc}header{display:flex;justify-content:space-between;align-items:center;gap:20px}section{margin-top:28px;background:#19212e;border:1px solid #29354a;border-radius:12px;padding:20px}h2{font-size:17px;margin:0 0 14px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #29354a;vertical-align:top}th{font-size:12px;color:#99a8bc}td{overflow-wrap:anywhere}button,input{font:inherit;border:1px solid #3a4a64;border-radius:6px;padding:6px 10px;color:inherit;background:#233149}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}.pill{border-radius:4px;background:#263750;padding:3px 7px;font-size:12px}.sub{font-size:12px;color:#99a8bc}#error{color:#ffb3a2;white-space:pre-wrap}.scroll{overflow:auto}#login{display:flex;gap:8px}#login input{flex:1}@media(max-width:700px){main{padding:22px 14px}header{display:block}section{padding:12px}table{min-width:650px}}
</style>
<main><header><div><h1>AGI Hub</h1><p>本机协作边车 · 原生助手会话</p></div><div><span class="sub">当前 leader</span><br><strong id="leader">未设置</strong></div></header>
<div id="login"><input id="token" type="password" placeholder="本机管理密钥"><button id="connect">连接</button></div><p id="error"></p>
<section><h2>助手会话</h2><div class="scroll"><table><thead><tr><th>助手</th><th>会话状态</th><th>空闲唤醒</th><th>忙时收成果</th><th>发送方式</th><th>角色</th></tr></thead><tbody id="endpoints"></tbody></table></div></section>
<section><h2>任务与成果</h2><div class="scroll"><table><thead><tr><th>任务</th><th>接收方</th><th>投递</th><th>执行</th><th>成果位置</th></tr></thead><tbody id="tasks"></tbody></table></div><p class="sub">已投递只表示入口接受了消息。执行成功与结果返回原入口分别记录；投递不确定的消息会保留，等待核实。</p></section>
<section><h2>使用边界</h2><p>初始化后的助手均未启用。绑定指定会话、验证原生唤醒后启用；重启后先核实会话状态。跨电脑文件传输尚未接入；独立 CLI 与桌面原生接入分别验证。</p></section></main>
<script>
let token=decodeURIComponent(location.hash.slice(1)), controller;
history.replaceState(null,'',location.pathname);document.getElementById('token').value=token;
const el=id=>document.getElementById(id);const labels={unknown:'待核实',idle:'空闲',busy:'执行中',needs_user:'需要你处理',waiting:'待接手',accepted:'已接手',running:'执行中',succeeded:'成功',failed:'失败',interrupted:'已停止',pending:'排队中',dispatching:'正在投递',delivered:'已投递',uncertain:'投递不确定'};
function cell(row,value,cls){const td=document.createElement('td');td.textContent=value;if(cls)td.className=cls;row.append(td);return td}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(await r.text());return r.json()}
async function refresh(){try{const s=await api('/v1/state');el('leader').textContent=s.leader||'未设置';el('endpoints').replaceChildren();for(const e of Object.values(s.endpoints)){const tr=document.createElement('tr');cell(tr,e.id+(e.enabled?'':' · 未启用'));cell(tr,labels[s.sessions[e.id]?.state]||'待核实');cell(tr,e.idle_wake_verified?'配置声明已验证':'尚未验证');cell(tr,e.result_queue_while_busy_verified?'配置声明已验证':'尚未验证');cell(tr,(e.modes||[]).join(' / '));const td=cell(tr,'');if(e.id===s.leader){td.textContent='当前 leader'}else{const b=document.createElement('button');b.textContent='设为 leader';b.disabled=!e.enabled||!(e.idle_wake_verified||e.result_queue_while_busy_verified);b.onclick=async()=>{try{await api('/v1/leader',{endpoint:e.id});await refresh()}catch(e){el('error').textContent=e.message}};td.append(b)}el('endpoints').append(tr)}el('tasks').replaceChildren();for(const t of Object.values(s.tasks).reverse()){const tr=document.createElement('tr');cell(tr,t.goal+' · '+t.id);cell(tr,t.recipient);const ms=Object.values(s.messages).filter(m=>m.task_id===t.id);cell(tr,ms.map(m=>(m.kind==='result'?'返回：':'任务：')+(labels[m.delivery]||m.delivery)).join(' / '));cell(tr,labels[t.execution]||t.execution);cell(tr,(t.artifacts||[]).map(a=>a.device_id+' / '+a.workspace_id+' / '+a.path).join('\n')||t.summary||'—');el('tasks').append(tr)}el('error').textContent=''}catch(e){el('error').textContent=e.message}}
async function connect(){token=el('token').value;if(controller)controller.abort();controller=new AbortController();await refresh();try{const r=await fetch('/v1/events',{headers:{Authorization:'Bearer '+token},signal:controller.signal});if(!r.ok)throw Error(await r.text());el('login').style.display='none';const reader=r.body.getReader(),d=new TextDecoder();let pending='';while(true){const chunk=await reader.read();if(chunk.done)break;pending+=d.decode(chunk.value,{stream:true});let i;while((i=pending.indexOf('\n\n'))>=0){const frame=pending.slice(0,i);pending=pending.slice(i+2);if(frame.includes('event: change'))await refresh()}}el('error').textContent='连接已断开，请重新连接';el('login').style.display='flex'}catch(e){if(e.name!=='AbortError'){el('error').textContent=e.message;el('login').style.display='flex'}}}
el('connect').onclick=connect;if(token)connect();
</script></html>`
